function render(){document.querySelectorAll('.nav-link').forEach(el=>{let on=el.dataset.view===state.view;el.classList.toggle('active',on);el.setAttribute('aria-current',on?'page':'false')});document.getElementById('app').innerHTML=({today,plan:roadmap,numbers,leads,studio,tools,settings:setup}[state.view]||today)()}
function nextMission(direction=1){let total=(state.week-1)*4+state.day-1+direction;if(total<0||total>103){toast(total>103?'You reached the last mission.':'You are at the first mission.');return}state.week=Math.floor(total/4)+1;state.day=total%4+1;state.showSteps=false;save();render();window.scrollTo({top:0,behavior:'smooth'})}
function copyText(t){if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(t).then(()=>toast('Copied. Fill in the blanks before sending.')).catch(()=>fallbackCopy(t))}else fallbackCopy(t)}
function fallbackCopy(t){const box=document.createElement('textarea');box.value=t;box.style.position='fixed';box.style.top='0';document.body.appendChild(box);box.select();try{document.execCommand('copy');toast('Copied. Fill in the blanks before sending.')}catch(e){toast('Copy this message by selecting the text.')}box.remove()}
function downloadBackup(){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString(),app:'Minesweepers Growth Playbook'},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='minesweepers-growth-backup-'+isoDate(new Date())+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Keep your backup somewhere private.')}
function numberFrom(id){const node=document.getElementById(id),value=node?.value;if(value===''||!Number.isFinite(Number(value))||Number(value)<0)throw Error('Enter zero or a positive number for every field.');return Number(value)}
document.addEventListener('click',e=>{
 let el=e.target.closest('[data-view]');if(el){go(el.dataset.view);return}
 if(e.target.closest('#homeLogo')){go('today');return}
 el=e.target.closest('[data-week]');if(el){state.week=Number(el.dataset.week);state.day=1;go('today');return}
 el=e.target.closest('[data-finish]');if(el){state.done[missionKey(state.week,state.day,Number(el.dataset.finish))]=true;save();render();return}
 if(e.target.closest('#showAll')){state.showSteps=!state.showSteps;save();render();return}
 if(e.target.closest('#nextDay')){if(state.week===26&&state.day===4)go('plan');else nextMission(1);return}
 if(e.target.closest('#previousDay')){nextMission(-1);return}
 if(e.target.closest('#saveNote')){state.notes[`${state.week}:${state.day}`]=document.getElementById('missionNote').value.trim();save();toast('Note saved.');return}
 if(e.target.closest('#saveFix')){state.chosenFix=document.getElementById('chosenFix').value.trim();save();toast('Your one thing is saved.');return}
 el=e.target.closest('[data-copy]');if(el){const v=WORDS.find(x=>x.id===el.dataset.copy);if(v)copyText(v.text);return}
 el=e.target.closest('[data-date]');if(el){const l=state.leads.find(x=>x.id===el.dataset.date);if(!l)return;let date=prompt('Next date (YYYY-MM-DD). Blank clears it:',l.next||'');if(date===null)return;if(date&&!/^\d{4}-\d{2}-\d{2}$/.test(date)){toast('Use a date like 2026-10-05.');return}l.next=date;save();render();return}
 el=e.target.closest('[data-edit]');if(el){const l=state.leads.find(x=>x.id===el.dataset.edit);if(!l)return;const v=prompt('Update short note:',l.notes||'');if(v===null)return;l.notes=v.slice(0,600);save();render();return}
 el=e.target.closest('[data-delete]');if(el){const l=state.leads.find(x=>x.id===el.dataset.delete);if(l&&confirm(`Delete ${l.name} from this device?`)){state.leads=state.leads.filter(x=>x.id!==l.id);save();render()}return}
 try{
 if(e.target.closest('#saveStudio')){for(const id of ['reviews','reviewRequests','videosRecorded','videosPosted','metaLeads','metaStarts']){const val=numberFrom('c-'+id);if(!Number.isInteger(val)||val>100000)throw Error('Use whole counts.');state[id]=val;}save();render();toast('Real counts saved.');return}
 if(e.target.closest('#saveReviewUrl')){const val=document.getElementById('reviewUrl').value.trim();if(val&&!/^https:\/\//i.test(val))throw Error('Use a secure https review link.');state.reviewUrl=val;save();toast('Review link saved.');return}
 if(e.target.closest('#copyReview')){copyText('Thanks for having Minesweepers clean your yard! If you have a minute, would you share your honest experience on Google? It helps neighbors know what to expect. '+(state.reviewUrl||'[Add your Google review link]'));return}
 if(e.target.closest('#saveRoutes')){state.stops=WEEKDAYS.map((_,i)=>numberFrom('r'+i));if(state.stops.some(v=>!Number.isInteger(v)||v>200))throw Error('Use whole stop counts between 0 and 200.');save();render();toast('Route visits saved.');return}
 if(e.target.closest('#saveScore')){let v={};for(let k of ['inquiries','quotes','starts','lost','cancels','reviewAsks','videos','metaQuotes','metaWins','spent']){const inp=document.getElementById('s-'+k);v[k]=inp.value===''?null:numberFrom('s-'+k);if(k!=='spent'&&v[k]!==null&&!Number.isInteger(v[k]))throw Error('Use whole counts.')}state.weekStats[state.week]=v;save();render();toast('Thursday scorecard saved.');return}
 if(e.target.closest('#saveMoney')){const price=numberFrom('avgPrice'),cash=numberFrom('cash'),hours=numberFrom('hours'),spent=numberFrom('spent');if(!confirm('Save the current route money and time figures?'))return;Object.assign(state,{price,weeklyCollected:cash,routeHours:hours,spent});save();render();toast('Money and time saved.');return}
 if(e.target.closest('#saveSetup')){let date=document.getElementById('start').value,budget=numberFrom('budget');if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||parseDate(date).getDay()!==1)throw Error('Choose a Monday start date.');state.start=date;state.budget=budget;save();render();toast('Setup saved.');return}
 }catch(err){toast(err.message);return}
 if(e.target.closest('#backup')){downloadBackup();return}
 if(e.target.closest('#restore')){document.getElementById('restoreFile').click();return}
 if(e.target.closest('#reset')){if(confirm('Erase ALL locally saved progress and leads from this device? Export first if needed.')){state=DEFAULT();save();render();toast('Local progress reset.')}return}
 });
document.addEventListener('change',e=>{if(e.target.dataset.check!==undefined){state.done[missionKey(state.week,state.day,Number(e.target.dataset.check))]=e.target.checked;save();render();return}if(e.target.dataset.status){const l=state.leads.find(x=>x.id===e.target.dataset.status);if(l){l.status=e.target.value;if(l.status==='Won'||l.status==='Lost')l.next='';save();render()}return}if(e.target.id==='restoreFile'){const file=e.target.files?.[0];if(!file)return;file.text().then(t=>{const obj=JSON.parse(t);if(![2,3].includes(obj.schema)||!Array.isArray(obj.stops)||obj.stops.length!==4||!Array.isArray(obj.leads)||!obj.done||!/\d{4}-\d{2}-\d{2}/.test(obj.start)||obj.week<1||obj.week>26)throw Error('Not a valid growth playbook backup');if(confirm('Replace ALL work on this device with this backup?')){state={...DEFAULT(),...obj,schema:3,view:'today'};delete state.exportedAt;delete state.app;save();render();toast('Backup restored.')}}).catch(()=>toast('Could not read this backup.'));return}});
document.addEventListener('submit',e=>{if(e.target.id!=='leadForm')return;e.preventDefault();const v=new FormData(e.target),name=String(v.get('name')||'').trim();if(!name){toast('Enter a name.');return}state.leads.unshift({id:globalThis.crypto?.randomUUID?.()||String(Date.now()),name,contact:String(v.get('contact')||'').trim(),area:String(v.get('area')||'').trim(),source:String(v.get('source')||'Other'),dogs:String(v.get('dogs')||''),next:String(v.get('next')||''),status:'New',notes:String(v.get('notes')||'').trim(),consent:v.get('consent')==='yes',created:isoDate(new Date())});save();render();toast('Lead saved. Give every open quote a next date.')});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();promptEvent=e;document.getElementById('installBtn').hidden=false});document.getElementById('installBtn').addEventListener('click',async()=>{if(!promptEvent)return;await promptEvent.prompt();await promptEvent.userChoice;promptEvent=null;document.getElementById('installBtn').hidden=true});
if('serviceWorker' in navigator&&location.protocol.startsWith('http'))window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(e=>console.warn('No offline install',e)));
render();
